mapper.select:
SELECT id, job_id, job_name, job_group, invoke_target, trigger_type, job_message, status, elapsed_time, created_at, updated_at, created_by, updated_by FROM log_job
AND job_id = #{query.jobId}
AND job_name LIKE CONCAT('%', #{query.jobName}, '%' )
AND job_group LIKE CONCAT('%', #{query.jobGroup}, '%' )
AND trigger_type = #{query.triggerType}
AND invoke_target LIKE CONCAT('%', #{query.invokeTarget}, '%' )
AND status = #{query.status}
AND elapsed_time = #{query.elapsedTime}
ORDER BY created_at DESC

SELECT id, job_id, job_name, job_group, invoke_target, trigger_type, job_message, status, exception_info, elapsed_time, created_at FROM log_job
AND job_name = #{jobName}
AND job_group = #{jobGroup}
ORDER BY created_at DESC LIMIT #{limit}

SELECT id, job_id, job_name, job_group, invoke_target, trigger_type, job_message, status, exception_info, elapsed_time, created_at FROM ( SELECT l.id, l.job_id, l.job_name, l.job_group, l.invoke_target, l.trigger_type, l.job_message, l.status, l.exception_info, l.elapsed_time, l.created_at, ROW_NUMBER() OVER (PARTITION BY l.job_id ORDER BY l.created_at DESC) AS row_num FROM log_job l WHERE l.job_id IN
#{jobId}
) latest WHERE latest.row_num = 1
